create table auditoria_acceso (codigo_respuesta number(10,0) not null, duracion_ms number(19,0) not null, fecha_hora timestamp(9) with time zone not null, id_auditoria_acceso number(19,0) generated by default as identity, id_usuario number(19,0), metodo_http varchar2(10 char) not null, codigo_registro varchar2(30 char), ip_cliente varchar2(45 char), correlation_id varchar2(80 char) not null, keycloak_subject varchar2(100 char), rol_snapshot varchar2(100 char), ruta_normalizada varchar2(300 char) not null, primary key (id_auditoria_acceso));
create table contador_codigo (anio number(10,0) not null, ultimo_numero number(10,0) not null, id_contador number(19,0) generated by default as identity, version number(19,0) not null, tipo_registro varchar2(20 char) not null check ((tipo_registro in ('INITIATIVE','PROJECT'))), primary key (id_contador), constraint UK_CONTADOR_TIPO_ANIO unique (tipo_registro, anio));
create table documento (ultima_version number(10,0) not null, id_documento number(19,0) generated by default as identity, id_registro number(19,0) not null, version number(19,0) not null, estado varchar2(30 char) not null check ((estado in ('PENDING','LOADED','NOT_APPLICABLE'))), tipo_documento varchar2(60 char) not null check ((tipo_documento in ('PUBLIC_INNOVATION_INITIATIVE_SHEET','INITIATIVE_TECHNICAL_OPINION','FORMAL_APPROVAL_DECISION','FINAL_PRODUCT_APPROVAL','PROJECT_MANAGEMENT_DOCUMENTATION','FINAL_CLOSURE_REPORT'))), motivo_no_aplica varchar2(500 char), primary key (id_documento), constraint UK_DOCUMENTO_REGISTRO_TIPO unique (id_registro, tipo_documento));
create table documento_contenido (id_documento_contenido number(19,0) generated by default as identity, id_documento_version number(19,0) not null unique, contenido blob not null, primary key (id_documento_contenido));
create table documento_version (numero_version number(10,0) not null, publicado_externo number(1,0) not null check ((publicado_externo in (0,1))), fecha_carga timestamp(9) with time zone not null, fecha_publicacion timestamp(9) with time zone, id_documento number(19,0) not null, id_documento_version number(19,0) generated by default as identity, tamanio_bytes number(19,0) not null, version_optimista number(19,0) not null, checksum_sha256 varchar2(64 char) not null, cargado_por varchar2(100 char) not null, publicado_por varchar2(100 char), tipo_mime varchar2(120 char) not null, nombre_archivo varchar2(255 char) not null, primary key (id_documento_version), constraint UK_DOC_VERSION unique (id_documento, numero_version));
create table evento_auditoria (fecha_evento timestamp(9) with time zone not null, id_evento number(19,0) generated by default as identity, id_usuario number(19,0), codigo_entidad varchar2(40 char) not null, tipo_entidad varchar2(60 char) not null, actor_subject varchar2(100 char) not null, tipo_evento varchar2(100 char) not null, detalle_json clob not null, primary key (id_evento));
create table institucion (activo number(1,0) not null check ((activo in (0,1))), id_institucion number(19,0) generated by default as identity, version number(19,0) not null, codigo varchar2(30 char) not null, nombre varchar2(200 char) not null, primary key (id_institucion), constraint UK_INSTITUCION_CODIGO unique (codigo));
create table notificacion (leida number(1,0) not null check ((leida in (0,1))), fecha_creacion timestamp(9) with time zone not null, fecha_lectura timestamp(9) with time zone, id_notificacion number(19,0) generated by default as identity, id_registro number(19,0), id_usuario_destinatario number(19,0) not null, tipo varchar2(60 char) not null, mensaje varchar2(500 char) not null, primary key (id_notificacion));
create table registro_portafolio (fecha_cierre date, fecha_inicio date not null, fecha_creacion timestamp(9) with time zone not null, fecha_modificacion timestamp(9) with time zone not null, id_registro number(19,0) generated by default as identity, id_registro_origen number(19,0), id_unidad_ejecutora number(19,0) not null, version number(19,0) not null, componente_digital varchar2(10 char) not null check ((componente_digital in ('YES','NO'))), codigo varchar2(20 char) not null, tipo_registro varchar2(20 char) not null check ((tipo_registro in ('INITIATIVE','PROJECT'))), estado varchar2(40 char) not null check ((estado in ('PRESENTED','INITIATIVE_APPROVED','INITIATIVE_ARCHIVED','PROJECT_IN_PROGRESS','PRODUCT_APPROVED','PRODUCT_NOT_APPROVED','SUSPENDED','CANCELLED','FINISHED','NOT_APPLICABLE','NOT_ADMISSIBLE'))), fuente_origen varchar2(40 char) not null check ((fuente_origen in ('INITIATIVE_SHEET','INTERNAL_CONTEST','OPEN_INNOVATION','MANAGEMENT_PROPOSAL','OTHER','CALL'))), modo_origen varchar2(40 char) check ((modo_origen in ('DERIVED_FROM_INITIATIVE','PREEXISTING'))), tipo_producto_final varchar2(40 char) not null check ((tipo_producto_final in ('CONCEPTUAL_PROTOTYPE','FUNCTIONAL_SOLUTION','NA'))), tipo_solucion varchar2(40 char) not null check ((tipo_solucion in ('POTENTIAL_OR_ADAPTABLE','TO_BE_DEFINED','NOT_APPLICABLE'))), creado_por varchar2(100 char) not null, nombre varchar2(180 char) not null, responsable varchar2(300 char) not null, actividad_poi varchar2(500 char), objetivo_pei varchar2(500 char), nota varchar2(600 char), descripcion clob not null, resultados_clave clob, primary key (id_registro), constraint UK_REGISTRO_CODIGO unique (codigo), constraint UK_REGISTRO_ORIGEN unique (id_registro_origen));
create table registro_unidad_responsable (orden_presentacion number(10,0) not null, id_registro number(19,0) not null, id_registro_unidad number(19,0) generated by default as identity, id_unidad_organica number(19,0), denominacion_original varchar2(300 char) not null, primary key (id_registro_unidad), constraint UK_RUR_REGISTRO_ORDEN unique (id_registro, orden_presentacion));
create table rol (activo number(1,0) not null check ((activo in (0,1))), sistema number(1,0) not null check ((sistema in (0,1))), id_rol number(19,0) generated by default as identity, codigo varchar2(40 char) not null check ((codigo in ('ADMINISTRADOR_PIIP','CONSULTA_EXTERNA'))), nombre varchar2(100 char) not null, primary key (id_rol), constraint UK_ROL_CODIGO unique (codigo));
create table tarea_trabajo (fecha_vencimiento date, fecha_completado timestamp(9) with time zone, fecha_creacion timestamp(9) with time zone not null, id_registro number(19,0) not null, id_tarea number(19,0) generated by default as identity, id_usuario_asignado number(19,0) not null, version number(19,0) not null, estado varchar2(20 char) not null check ((estado in ('PENDING','COMPLETED','CANCELLED'))), prioridad varchar2(20 char) not null check ((prioridad in ('HIGH','MEDIUM'))), tipo_tarea varchar2(40 char) not null check ((tipo_tarea in ('REGISTER_DECISION','CREATE_DERIVED_PROJECT'))), evento_origen varchar2(100 char) not null, descripcion varchar2(400 char) not null, primary key (id_tarea));
create table unidad_ejecutora (activo number(1,0) not null check ((activo in (0,1))), id_institucion number(19,0) not null, id_unidad_ejecutora number(19,0) generated by default as identity, version number(19,0) not null, codigo varchar2(30 char) not null, nombre varchar2(200 char) not null, primary key (id_unidad_ejecutora), constraint UK_UE_INSTITUCION_CODIGO unique (id_institucion, codigo));
create table unidad_organica (activo number(1,0) not null check ((activo in (0,1))), id_unidad_ejecutora number(19,0) not null, id_unidad_organica number(19,0) generated by default as identity, id_unidad_padre number(19,0), version number(19,0) not null, codigo varchar2(30 char) not null, sigla varchar2(30 char), nombre varchar2(200 char) not null, primary key (id_unidad_organica), constraint UK_UO_EJECUTORA_CODIGO unique (id_unidad_ejecutora, codigo));
create table usuario (activo number(1,0) not null check ((activo in (0,1))), id_usuario number(19,0) generated by default as identity, ultima_autenticacion timestamp(9) with time zone, version number(19,0) not null, keycloak_subject varchar2(100 char) not null, correo varchar2(200 char) not null, nombre_completo varchar2(300 char) not null, primary key (id_usuario), constraint UK_USUARIO_SUBJECT unique (keycloak_subject));
create table usuario_rol_ambito (activo number(1,0) not null check ((activo in (0,1))), fecha_asignacion timestamp(9) with time zone not null, id_institucion number(19,0) not null, id_rol number(19,0) not null, id_unidad_ejecutora number(19,0), id_usuario number(19,0) not null, id_usuario_rol_ambito number(19,0) generated by default as identity, version number(19,0) not null, vigente_desde timestamp(9) with time zone not null, vigente_hasta timestamp(9) with time zone, asignado_por varchar2(100 char) not null, primary key (id_usuario_rol_ambito));
create index IDX_AUDIT_ACCESO_FECHA on auditoria_acceso (fecha_hora);
create index IDX_EVENTO_ENTIDAD on evento_auditoria (tipo_entidad, codigo_entidad);
create index IDX_NOTIF_DESTINATARIO_LEIDA on notificacion (id_usuario_destinatario, leida);
create index IDX_REGISTRO_TIPO_ESTADO on registro_portafolio (tipo_registro, estado);
create index IDX_REGISTRO_EJECUTORA on registro_portafolio (id_unidad_ejecutora);
create index IDX_TAREA_ASIGNADO_ESTADO on tarea_trabajo (id_usuario_asignado, estado);
create index IDX_URA_USUARIO_ACTIVO on usuario_rol_ambito (id_usuario, activo);
create index IDX_URA_EJECUTORA on usuario_rol_ambito (id_unidad_ejecutora);
